# # # #             "fps":                fps,
# # # #             "size_mb":            size_mb,
# # # #             "total_frames":       total_frames,
# # # #         }

# # # #         print(
# # # #             f"[Analyzer:{job_id}]  [{idx + 1}/{n_videos}]  "
