# # #         frame_offset += total_frames

# # #         # ── Fix 5: memory/resource snapshot — after this video ───────────────
# # #         _log_resource_snapshot("VIDEO END", job_id=job_id,
# # #                                 violations=len(shared_vstore._violations))

# # #         # Report per-video progress (10%–90% band)
